arguments.content:
:root {
  --primary: #1868DB;
  --primary-hover: #1456B5;
  --accent: #FF613D;
  --accent-hover: #E55535;
  --text-dark: #292A2E;
  --text-light: #6B6C70;
  --bg-white: #FFFFFF;
  --bg-light: #F8F9FB;
  --bg-gray: #F0F2F5;
  --purple-accent: #7B61FF;
  --border-color: #E2E4E8;
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;
  --transition: all 0.2s ease-in-out;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 24px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.05);
  --shadow-md: 0 8px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 24px 48px rgba(24, 104, 219, 0.15);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  color: var(--text-dark);
  background-color: var(--bg-white);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--primary-hover);
}

ul {
  list-style: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
h1, h2, h3, h4 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-dark);
}

h1 { font-size: 3.5rem; letter-spacing: -0.02em; margin-bottom: 1.5rem; }
h2 { font-size: 2.5rem; letter-spacing: -0.01em; margin-bottom: 1rem; }
h3 { font-size: 1.5rem; margin-bottom: 0.75rem; }
p { font-size: 1.125rem; color: var(--text-light); margin-bottom: 1.5rem; }
.small-text { font-size: 0.875rem; color: var(--text-light); }

/* Navigation */
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
  background: var(--bg-white);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: linear-gradient(135deg, var(--purple-accent), var(--primary));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-links {
  display: flex;
  gap: 2rem;
  align-items: center;
}

.nav-links a {
  color: var(--text-dark);
  font-weight: 500;
}

.nav-links a:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 50px;
  cursor: pointer;
  transition: var(--transition);
  border: 2px solid transparent;
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-hover);
  color: white;
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: white;
  color: var(--text-dark);
  border-color: var(--border-color);
}

.btn-secondary:hover {
  border-color: var(--text-dark);
}

.btn-accent {
  background: var(--accent);
  color: white;
}
.btn-accent:hover {
  background: var(--accent-hover);
  color: white;
}

.btn-outline {
  border-color: var(--primary);
  color: var(--primary);
  background: transparent;
}
.btn-outline:hover {
  background: var(--primary);
  color: white;
}

/* Sections */
.section {
  padding: 6rem 0;
}

.section-light {
  background: var(--bg-light);
}

.text-center {
  text-align: center;
}

.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-8 { margin-bottom: 2rem; }
.mt-4 { margin-top: 1rem; }
.mt-8 { margin-top: 2rem; }

/* Grid Layouts */
.grid {
  display: grid;
  gap: 2rem;
}

.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

/* Hero Section */
.hero {
  padding: 8rem 0 6rem;
  text-align: center;
  background: linear-gradient(180deg, rgba(123, 97, 255, 0.05) 0%, rgba(255, 255, 255, 0) 100%);
}

.hero h1 {
  max-width: 800px;
  margin: 0 auto 1.5rem;
  background: linear-gradient(135deg, var(--text-dark), var(--primary));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero p {
  max-width: 600px;
  margin: 0 auto 2rem;
  font-size: 1.25rem;
}

.hero-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

.hero-mockup {
  margin-top: 4rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  border: 1px solid var(--border-color);
}
.hero-mockup img {
  width: 100%;
  display: block;
  background-color: var(--bg-gray);
  min-height: 400px;
  object-fit: cover;
}

/* Logo Bar */
.logo-bar {
  padding: 3rem 0;
  border-bottom: 1px solid var(--border-color);
  text-align: center;
}

.logo-bar p {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
  margin-bottom: 1.5rem;
}

.logo-grid {
  display: flex;
  justify-content: center;
  gap: 3rem;
  flex-wrap: wrap;
  align-items: center;
  opacity: 0.6;
}

.logo-grid span {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-dark);
}

/* Feature Blocks */
.feature-block {
  display: flex;
  align-items: center;
  gap: 4rem;
}
.feature-block.reverse {
  flex-direction: row-reverse;
}
.feature-content {
  flex: 1;
}
.feature-visual {
  flex: 1;
  background: var(--bg-light);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 1px solid var(--border-color);
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: var(--purple-accent);
  color: white;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

/* Cards */
.card {
  background: white;
  border-radius: var(--radius-md);
  padding: 2rem;
  border: 1px solid var(--border-color);
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}
.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

/* Pricing Page Specific */
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 2rem;
}
.switch {
  position: relative;
  display: inline-block;
  width: 60px;
  height: 34px;
}
.switch input { opacity: 0; width: 0; height: 0; }
.slider {
  position: absolute;
  cursor: pointer;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--border-color);
  transition: .4s;
  border-radius: 34px;
}
.slider:before {
  position: absolute;
  content: "";
  height: 26px; width: 26px;
  left: 4px; bottom: 4px;
  background-color: white;
  transition: .4s;
  border-radius: 50%;
}
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(26px); }

.save-badge {
  background: rgba(26, 219, 116, 0.15);
  color: #0E9F52;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  margin-bottom: 4rem;
}

.pricing-card {
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  background: white;
  position: relative;
}
.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: scale(1.05);
  z-index: 2;
}
.popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: 0.25rem 1rem;
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-price {
  font-size: 3rem;
  font-weight: 800;
  margin: 1rem 0;
  color: var(--text-dark);
}
.pricing-price span {
  font-size: 1rem;
  color: var(--text-light);
  font-weight: 400;
}

.pricing-features {
  margin-top: 2rem;
  flex: 1;
}
.pricing-features li {
  margin-bottom: 1rem;
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  font-size: 0.875rem;
}
.pricing-features li::before {
  content: '✓';
  color: var(--primary);
  font-weight: bold;
}

.comparison-table-wrapper {
  overflow-x: auto;
  margin-top: 4rem;
}
.comparison-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}
.comparison-table th, .comparison-table td {
  padding: 1.5rem 1rem;
  border-bottom: 1px solid var(--border-color);
}
.comparison-table th {
  background: var(--bg-light);
  font-weight: 600;
  position: sticky;
  top: 0;
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--border-color);
}
.faq-question {
  padding: 1.5rem 0;
  cursor: pointer;
  font-weight: 600;
  font-size: 1.125rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}
.faq-answer p {
  padding-bottom: 1.5rem;
  margin: 0;
}
.faq-question::after {
  content: '+';
  font-size: 1.5rem;
  transition: transform 0.3s;
}
.faq-item.active .faq-answer {
  max-height: 500px;
}
.faq-item.active .faq-question::after {
  transform: rotate(45deg);
}

/* Auth Pages */
.auth-layout {
  min-height: 100vh;
  display: flex;
}
.auth-form-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 2rem;
}
.auth-box {
  width: 100%;
  max-width: 400px;
}
.auth-sidebar {
  flex: 1;
  background: linear-gradient(135deg, var(--bg-light), var(--primary));
  padding: 4rem;
  display: flex;
  align-items: center;
  color: white;
}
.auth-sidebar h2 { color: white; }
.auth-sidebar p { color: rgba(255,255,255,0.9); }

.form-group {
  margin-bottom: 1.5rem;
}
.form-label {
  display: block;
  font-weight: 500;
  margin-bottom: 0.5rem;
}
.form-input {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-family: var(--font-family);
}
.form-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(24, 104, 219, 0.1);
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  width: 100%;
  padding: 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: white;
  font-weight: 500;
  cursor: pointer;
  margin-bottom: 1rem;
  transition: var(--transition);
}
.social-btn:hover {
  background: var(--bg-light);
}

.divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 1.5rem 0;
  color: var(--text-light);
}
.divider::before, .divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--border-color);
}
.divider::before { margin-right: .5em; }
.divider::after { margin-left: .5em; }

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 2rem;
  left: 2rem;
  right: 2rem;
  background: white;
  padding: 1.5rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 1000;
  border: 1px solid var(--border-color);
}
.cookie-banner.hidden {
  display: none;
}
.cookie-actions {
  display: flex;
  gap: 1rem;
}

/* Modals */
.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1001;
  opacity: 0;
  visibility: hidden;
  transition: var(--transition);
}
.modal-overlay.active {
  opacity: 1;
  visibility: visible;
}
.modal-content {
  background: white;
  padding: 2rem;
  border-radius: var(--radius-md);
  width: 100%;
  max-width: 500px;
}

/* Footer */
footer {
  background: var(--bg-light);
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border-color);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 2rem;
  margin-bottom: 4rem;
}
.footer-col h4 {
  font-size: 1rem;
  margin-bottom: 1rem;
}
.footer-col ul li {
  margin-bottom: 0.5rem;
}
.footer-col ul a {
  color: var(--text-light);
  font-size: 0.875rem;
}
.footer-col ul a:hover {
  color: var(--primary);
}

/* Utils */
.w-full { width: 100%; }

@media (max-width: 768px) {
  .nav-links, .nav-actions { display: none; }
  .grid-2, .grid-3, .grid-4, .pricing-cards, .footer-grid { grid-template-columns: 1fr; }
  .feature-block, .feature-block.reverse { flex-direction: column; }
  .auth-layout { flex-direction: column; }
  .hero h1 { font-size: 2.5rem; }
  .cookie-banner { flex-direction: column; gap: 1rem; text-align: center; }
}
